import React, { useRef } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';

const Article = () => {
  const { slug } = useParams();
  const navigate = useNavigate();
  const touchStartX = useRef(null);
  const touchStartY = useRef(null);

  const handleTouchStart = (event) => {
    const touch = event.touches[0];
    touchStartX.current = touch.clientX;
    touchStartY.current = touch.clientY;
  };

  const handleTouchEnd = (event) => {
    if (touchStartX.current === null || touchStartY.current === null) {
      return;
    }

    const touch = event.changedTouches[0];
    const deltaX = touchStartX.current - touch.clientX;
    const deltaY = Math.abs(touchStartY.current - touch.clientY);

    touchStartX.current = null;
    touchStartY.current = null;

    if (deltaX > 70 && deltaY < 60) {
      navigate('/blog');
    }
  };

  return (
    <div
      className="pg"
      id="page-article"
      onTouchStart={handleTouchStart}
      onTouchEnd={handleTouchEnd}
    >
      <div className="sec">
        <div style={{ marginBottom: '2rem' }}>
          <Link to="/blog" className="back-link" style={{
            display: 'inline-flex',
            alignItems: 'center',
            color: '#666',
            textDecoration: 'none',
            fontSize: '1rem',
            fontWeight: '500'
          }}>
            ← Back to Blog
          </Link>
        </div>

        <div className="artbody">
          <h1>Article: {slug}</h1>
          <p>This is a placeholder for the article content. The article slug is: <strong>{slug}</strong></p>

          <h2>Introduction</h2>
          <p>Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.</p>

          <h2>Main Content</h2>
          <p>Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat.</p>

          <p>Duis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur.</p>

          <h2>Conclusion</h2>
          <p>Excepteur sint occaecat cupidatat non proident, sunt in culpa qui officia deserunt mollit anim id est laborum.</p>
        </div>
      </div>
    </div>
  );
};

export default Article;
